static const int REG_NUM = 32;

class RegisterFile {
public:
    Immediate prev[REG_NUM];
    Immediate next[REG_NUM];

    RegisterFile();

    void tick();

    Immediate read(int id);

    void write(int id, Immediate val);

    void debug();
};

RegisterFile::RegisterFile() {
    memset(prev, 0, sizeof(prev));
    memset(next, 0, sizeof(next));
}

void RegisterFile::tick() {
    memcpy(prev, next, sizeof(prev));
}

Immediate RegisterFile::read(int id) {
    if (id == 0) {
        return 0;
    } else {
        return prev[id];
    }
}

void RegisterFile::write(int id, Immediate val) {
    next[id] = val;
}

void RegisterFile::debug() {
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 8; ++j) {
            int id = i * 8 + j;
            if (id < REG_NUM) {
                std::cout << "#" << std::setw(2) << id << ":";
                debug_immediate(next[id], 11);
                std::cout << "(";
                // Add register name based on ID (ra, sp, gp, tp, t0-t6, s0-s11, a0-a7)
                if (id == 0) {
                    std::cout << "ra";
                } else if (id == 1) {
                    std::cout << "sp";
                } else if (id == 2) {
                    std::cout << "gp";
                } else if (id == 3) {
                    std::cout << "tp";
                } else if (id >= 4 && id <= 10) {
                    std::cout << "t" << id - 4;
                } else if (id >= 11 && id <= 21) {
                    std::cout << "s" << id - 11;
                } else if (id >= 22 && id <= 28) {
                    std::cout << "a" << id - 22;
                }
                std::cout << ")\t";
            }
        }
        std::cout << std::endl;
    }
}
